SELECT i_category, loss_category, COUNT(DISTINCT wr_reason_sk) AS distinct_reasons, AVG(total_loss) AS avg_loss, SUM(return_cnt) AS total_returns FROM ( SELECT wr.wr_reason_sk, i.i_category, SUM(wr.wr_net_loss) AS total_loss, COUNT(*) AS return_cnt, CASE WHEN SUM(wr.wr_net_loss) > 18000 THEN 'HIGH' WHEN SUM(wr.wr_net_loss) > 9000 THEN 'MEDIUM' ELSE 'LOW' END AS loss_category FROM web_returns wr JOIN item i ON wr.wr_item_sk = i.i_item_sk JOIN customer_address ca ON wr.wr_returning_addr_sk = ca.ca_address_sk WHERE ca.ca_country = 'USA' GROUP BY wr.wr_reason_sk, i.i_category ) agg GROUP BY i_category, loss_category HAVING AVG(total_loss) > 10000 ORDER BY avg_loss DESC
